// ❌ OLD: Required writing C++ glue code, configuring binding.gyp,
// and compiling with node-gyp on every machine.
#include <napi.h>

Napi::Number AddWrapped(const Napi::CallbackInfo& info) {
  Napi::Env env = info.Env();
  int a = info[0].As<Napi::Number>().Int32Value();
  int b = info[1].As<Napi::Number>().Int32Value();
  return Napi::Number::New(env, a + b);
}

Napi::Object Init(Napi::Env env, Napi::Object exports) {
  exports.Set("add", Napi::Function::New(env, AddWrapped));
  return exports;
}
NODE_API_MODULE(addon, Init)

import { dlopen, FFIType, suffix } from 'bun:ffi';

// ✅ NEW: Open raw pre-compiled shared library directly in TypeScript!
const libPath = `./libmath.${suffix}`;

const { symbols } = dlopen(libPath, {
  add: {
    args: [FFIType.i32, FFIType.i32],
    returns: FFIType.i32,
  },
  get_version: {
    args: [],
    returns: FFIType.cstring,
  }
});

console.log('Result:', symbols.add(10, 20)); // 30
console.log('Version:', symbols.get_version());
